settings.colorFunction:
var type = dsData[dsIndex]['Type'];

if (type === 'colorpin') {
    var lastConnectTime = dsData[dsIndex]['lastConnectTime']; // Timestamp in ms
    var now = Date.now();

    // 5 minutes = 300,000 milliseconds
    var offlineTooLong = !lastConnectTime || (now - lastConnectTime > 5 * 60 * 1000);

    return offlineTooLong ? 'red' : 'green';
}

